CREATE TABLE "TB_INV_FLOW_FILE" (
  "INV_FLOW_FILE_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "SOURCE_FILE_NM" VARCHAR(500) NOT NULL,
  "SOURCE_REL_PATH" VARCHAR(1000) NOT NULL,
  "FILE_HASH" VARCHAR(64) NOT NULL,
  "SCOPE_TP" VARCHAR(10) NOT NULL,
  "SCOPE_KEY" VARCHAR(100) NOT NULL,
  "MKT_CD" VARCHAR(20) NOT NULL,
  "STK_CD" VARCHAR(30),
  "STK_NM" VARCHAR(200),
  "METRIC_TP" VARCHAR(10) NOT NULL,
  "TRADE_TP" VARCHAR(10) NOT NULL,
  "UNIT_MULT" NUMERIC(20,4) NOT NULL DEFAULT 1,
  "IMPORT_STATUS" VARCHAR(20) NOT NULL,
  "ROW_CNT" INTEGER NOT NULL DEFAULT 0,
  "MIN_BASE_DT" DATE,
  "MAX_BASE_DT" DATE,
  "ERROR_MSG" VARCHAR(2000),
  "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "MOD_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UK_TB_INV_FLOW_FILE_01" UNIQUE ("FILE_HASH"),
  CONSTRAINT "CK_TB_INV_FLOW_FILE_01" CHECK ("SCOPE_TP" IN ('MARKET','STOCK')),
  CONSTRAINT "CK_TB_INV_FLOW_FILE_02" CHECK ("METRIC_TP" IN ('AMOUNT','VOLUME')),
  CONSTRAINT "CK_TB_INV_FLOW_FILE_03" CHECK ("TRADE_TP" IN ('SELL','BUY','NET_BUY')),
  CONSTRAINT "CK_TB_INV_FLOW_FILE_04" CHECK ("IMPORT_STATUS" IN ('COMPLETED','FAILED'))
);

CREATE INDEX "IX_TB_INV_FLOW_FILE_01" ON "TB_INV_FLOW_FILE" ("SCOPE_TP","SCOPE_KEY","METRIC_TP","TRADE_TP");

CREATE TABLE "TB_INV_FLOW_RAW_ROW" (
  "INV_FLOW_FILE_ID" BIGINT NOT NULL REFERENCES "TB_INV_FLOW_FILE"("INV_FLOW_FILE_ID") ON DELETE CASCADE,
  "BASE_DT" DATE NOT NULL,
  "INVESTOR_TP" VARCHAR(30) NOT NULL,
  "RAW_VAL" NUMERIC(30,4) NOT NULL,
  CONSTRAINT "PK_TB_INV_FLOW_RAW_ROW" PRIMARY KEY ("INV_FLOW_FILE_ID","BASE_DT","INVESTOR_TP")
);

CREATE INDEX "IX_TB_INV_FLOW_RAW_ROW_01" ON "TB_INV_FLOW_RAW_ROW" ("BASE_DT","INVESTOR_TP");

CREATE TABLE "TB_INV_FLOW_DAY" (
  "SCOPE_TP" VARCHAR(10) NOT NULL,
  "SCOPE_KEY" VARCHAR(100) NOT NULL,
  "MKT_CD" VARCHAR(20) NOT NULL,
  "STK_CD" VARCHAR(30),
  "STK_NM" VARCHAR(200),
  "BASE_DT" DATE NOT NULL,
  "INVESTOR_TP" VARCHAR(30) NOT NULL,
  "SELL_QTY" NUMERIC(30,4),
  "BUY_QTY" NUMERIC(30,4),
  "NET_BUY_QTY" NUMERIC(30,4),
  "SELL_AMT" NUMERIC(30,4),
  "BUY_AMT" NUMERIC(30,4),
  "NET_BUY_AMT" NUMERIC(30,4),
  "NET_QTY_DERIVED_YN" CHAR(1) NOT NULL DEFAULT 'N',
  "NET_AMT_DERIVED_YN" CHAR(1) NOT NULL DEFAULT 'N',
  "SOURCE_DATA_HASH" VARCHAR(64) NOT NULL,
  "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "MOD_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "PK_TB_INV_FLOW_DAY" PRIMARY KEY ("SCOPE_TP","SCOPE_KEY","BASE_DT","INVESTOR_TP"),
  CONSTRAINT "CK_TB_INV_FLOW_DAY_01" CHECK ("SCOPE_TP" IN ('MARKET','STOCK')),
  CONSTRAINT "CK_TB_INV_FLOW_DAY_02" CHECK ("NET_QTY_DERIVED_YN" IN ('Y','N') AND "NET_AMT_DERIVED_YN" IN ('Y','N'))
);

CREATE INDEX "IX_TB_INV_FLOW_DAY_01" ON "TB_INV_FLOW_DAY" ("BASE_DT" DESC,"INVESTOR_TP");
CREATE INDEX "IX_TB_INV_FLOW_DAY_02" ON "TB_INV_FLOW_DAY" ("STK_CD","BASE_DT" DESC);

COMMENT ON TABLE "TB_INV_FLOW_FILE" IS 'KRX 투자자별 거래실적 Excel 원본 파일 Import 이력';
COMMENT ON TABLE "TB_INV_FLOW_RAW_ROW" IS '파일별 날짜·투자자 원본 값';
COMMENT ON TABLE "TB_INV_FLOW_DAY" IS '시장 또는 종목별 투자자 일별 매도·매수·순매수 정규화 값';
COMMENT ON COLUMN "TB_INV_FLOW_DAY"."NET_AMT_DERIVED_YN" IS '순매수금액 파일 부재 시 매수금액-매도금액 파생 여부';
